state.output:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background: #f4f6f8;
  color: #263238;
  line-height: 1.6;
  overflow-x: hidden;
}

header {
  min-height: 70px;
  background: #17324d;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 8%;
}

header b {
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.5px;
}

nav {
  display: flex;
  align-items: center;
}

nav a {
  color: #e2e8f0;
  margin-left: 24px;
  text-decoration: none;
  font-weight: 500;
  font-size: 0.95rem;
  transition: color 0.2s ease;
}

nav a:hover {
  color: #ffffff;
}

.notice {
  width: 100%;
  background: #ffe3a3;
  color: #664d03;
  padding: 12px 8%;
  text-align: center;
  font-size: 0.9rem;
  font-weight: 500;
  border-bottom: 1px solid #fed88b;
}

.hero {
  padding: 80px 8%;
  min-height: 420px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  background: linear-gradient(90deg, rgba(16, 40, 61, 0.92), rgba(16, 40, 61, 0.65)), url('business.jpg') center/cover no-repeat;
  color: #fff;
}

.hero h1 {
  font-size: clamp(2.2rem, 5vw, 3rem);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 16px;
  max-width: 650px;
}

.hero p {
  font-size: clamp(1rem, 2.5vw, 1.15rem);
  color: #e0e7ef;
  line-height: 1.6;
  margin-bottom: 28px;
  max-width: 580px;
}

.btn,
button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  background: #e99112;
  color: #fff;
  border: 0;
  border-radius: 6px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
}

.btn:hover,
button:hover {
  background: #d37e07;
}

.btn:active,
button:active {
  transform: scale(0.98);
}

section {
  padding: 60px 8%;
}

section h2 {
  font-size: clamp(1.6rem, 3.5vw, 2.2rem);
  font-weight: 700;
  color: #17324d;
  margin-bottom: 28px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  width: 100%;
}

.card {
  background: #fff;
  padding: 28px;
  border-radius: 8px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
  border: 1px solid #e9ecef;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
}

.card h3 {
  font-size: 1.25rem;
  font-weight: 600;
  color: #17324d;
  margin-bottom: 12px;
}

.card p {
  font-size: 0.95rem;
  color: #546e7a;
  line-height: 1.6;
}

.contact {
  background: #ffffff;
  border-top: 1px solid #e2e8f0;
}

.contact h2 {
  margin-bottom: 12px;
}

.contact p {
  font-size: 1.05rem;
  color: #546e7a;
  margin-bottom: 24px;
}

footer {
  text-align: center;
  padding: 24px 8%;
  background: #10283d;
  color: #94a3b8;
  font-size: 0.9rem;
}

@media (max-width: 900px) {
  .grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 700px) {
  header {
    padding: 14px 5%;
    flex-wrap: wrap;
    gap: 12px;
  }

  nav a {
    margin-left: 16px;
  }

  .notice {
    padding: 12px 5%;
  }

  .hero {
    padding: 50px 5%;
    min-height: 360px;
  }

  section {
    padding: 45px 5%;
  }

  .grid {
    grid-template-columns: 1fr;
    gap: 18px;
    width: 100%;
  }

  footer {
    padding: 20px 5%;
  }
}

@media (max-width: 480px) {
  header {
    flex-direction: column;
    align-items: flex-start;
  }

  nav {
    width: 100%;
    justify-content: flex-start;
  }

  nav a {
    margin-left: 0;
    margin-right: 18px;
  }

  .hero button,
  .contact button {
    width: 100%;
  }
}

