}

.contact h2 {
  margin-bottom: 12px;
}

.contact p {
  font-size: 1.05rem;
  color: #546e7a;
  margin-bottom: 24px;
}

footer {
  text-align: center;
  padding: 24px 8%;
  background: #10283d;
  color: #94a3b8;
  font-size: 0.9rem;
}

