    gap: 12px;
  }

  nav a {
    margin-left: 16px;
  }

  .notice {
    padding: 12px 5%;
  }

  .hero {
    padding: 50px 5%;
    min-height: 360px;
  }

  section {
    padding: 45px 5%;
  }

  .grid {
    grid-template-columns: 1fr;
