:root {
  color-scheme: light;
  --navy: #17324d;
  --ink: #21364a;
  --muted: #526374;
  --gold: #edaf4d;
}
* { box-sizing: border-box; }
html { scroll-padding-top: 1.5rem; }
body {
  margin: 0;
  background: #f7f8fa;
  color: var(--ink);
  font-family: "Segoe UI", "Helvetica Neue", sans-serif;
  font-size: 1rem;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
}
h1, h2, h3, p { margin: 0; }
h1, h2, h3 { font-family: Georgia, "Times New Roman", serif; font-weight: 400; }
h1 { font-size: clamp(2.5rem, 5.5vw, 4.5rem); line-height: 1.12; letter-spacing: -0.035em; }
h2 { font-size: clamp(2rem, 3.5vw, 2.75rem); line-height: 1.2; letter-spacing: -0.025em; }
h3 { font-size: 1.5rem; line-height: 1.3; }
a { color: inherit; }
.container { width: min(calc(100% - 3rem), 70rem); margin-inline: auto; }
header { background: var(--navy); color: #fff; }
.header-content { display: flex; align-items: center; justify-content: space-between; gap: 1rem 2rem; min-height: 5rem; padding-block: 1rem; }
.brand { font-family: Georgia, "Times New Roman", serif; font-size: 1.5rem; line-height: 1.3; text-decoration: none; }
.brand span { color: #efc481; }
nav { display: flex; align-items: center; flex-wrap: wrap; gap: 0.25rem 1.5rem; }
nav a { display: inline-flex; align-items: center; min-height: 2.75rem; text-decoration: none; font-size: 0.9375rem; }
nav a:hover { color: #efc481; text-decoration: underline; text-underline-offset: 0.4rem; }
.notice { background: #fff0d4; color: #674714; padding-block: 0.75rem; font-size: 0.875rem; border-bottom: 1px solid #ecd9b6; }
.hero { display: flex; align-items: center; min-height: 28rem; padding-block: clamp(3.5rem, 7vw, 6rem); background: linear-gradient(90deg, #10283df5, #10283d99), url("business.jpg") center / cover; color: #fff; }
.hero-content { max-width: 42rem; }
.eyebrow { margin-bottom: 0.875rem; font-size: 0.75rem; font-weight: 600; letter-spacing: 0.15em; text-transform: uppercase; }
.hero .eyebrow { color: #efc481; }
.hero-description { max-width: 33rem; margin-block: 1.5rem 2rem; color: #e0e7ef; font-size: 1.125rem; }
.btn, button { display: inline-flex; align-items: center; justify-content: center; gap: 1.5rem; min-height: 3rem; padding: 0.75rem 1.5rem; border: 1px solid transparent; border-radius: 0.375rem; background: var(--gold); color: #172c3f; font: inherit; font-weight: 600; text-decoration: none; cursor: pointer; text-align: center; }
.btn:hover, button:hover { background: #f6c16c; }
.btn span { font-size: 1.25rem; line-height: 1; }
a:focus-visible, button:focus-visible { outline: 3px solid #a66100; outline-offset: 5px; }
header a:focus-visible, .hero a:focus-visible { outline-color: #ffda9a; }
.services { padding-block: clamp(3rem, 6vw, 5rem); }
.services .eyebrow, .contact .eyebrow { color: var(--muted); }
.grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.5rem; margin-top: 2rem; }
.card { min-width: 0; padding: clamp(1.5rem, 3vw, 2rem); background: #fff; border: 1px solid #e1e6eb; border-radius: 0.5rem; box-shadow: 0 5px 18px #17324d06; }
.card-number { display: block; margin-bottom: 1.5rem; color: #88601e; font-size: 0.8125rem; font-weight: 600; letter-spacing: 0.08em; }
.card p { margin-top: 0.75rem; color: var(--muted); }
.contact { padding-block: clamp(2.5rem, 5vw, 4rem); background: #eaf0f4; border-top: 1px solid #dce4eb; }
.contact-content { display: flex; align-items: center; justify-content: space-between; gap: 2rem; }
.contact h2 { margin-bottom: 0.875rem; }
.contact p:not(.eyebrow) { color: var(--muted); }
.contact .btn { flex-shrink: 0; }
footer { padding-block: 1.5rem; background: #10283d; color: #c5d0db; text-align: center; font-size: 0.8125rem; }
.skip-link { position: absolute; top: 0.75rem; left: 1.5rem; z-index: 1; padding: 0.75rem 1rem; transform: translateY(-200%); background: #fff; color: var(--navy); border-radius: 0.25rem; }
.skip-link:focus { transform: translateY(0); }
@media (max-width: 48rem) {
  .grid { grid-template-columns: 1fr; gap: 1rem; }
  .card { padding: 1.5rem; }
  .card-number { margin-bottom: 1rem; }
  .contact-content { align-items: flex-start; flex-direction: column; gap: 1.5rem; }
}
@media (max-width: 30rem) {
  .container { width: calc(100% - 2rem); }
  .header-content { flex-direction: column; align-items: flex-start; gap: 0.5rem; }
  nav { width: 100%; justify-content: space-between; gap: 0.25rem 1rem; }
  .hero { min-height: auto; }
  .hero-description { font-size: 1rem; }
  .btn { width: 100%; }
  .contact .btn { align-self: stretch; }
}

